import{Z as t,e as o,f as n,a0 as r}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Pardot","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/pardot.md","filePath":"integrations/crm/pardot.md","lastUpdated":1781267307000}'),i={name:"integrations/crm/pardot.md"};function s(a,e,l,c,h,d){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="pardot" tabindex="-1">Pardot <a class="header-anchor" href="#pardot" aria-label="Permalink to &quot;Pardot&quot;">​</a></h1><p>Connect Pardot to send enquiries to the records your team manages. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Pardot as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-pardot-api" tabindex="-1">Step 2. Connect to the Pardot API <a class="header-anchor" href="#step-2-connect-to-the-pardot-api" aria-label="Permalink to &quot;Step 2. Connect to the Pardot API&quot;">​</a></h3><ol><li>Go to <a href="https://www.salesforce.com" target="_blank">Pardot</a> and login to your account.</li><li>In the main menu, on the top-right, click the <strong>Settings</strong> icon and select <strong>Setup</strong>.</li><li>In the left-hand sidebar, click on <strong>Apps</strong> → <strong>App Manager</strong>.</li><li>Click the <strong>New Connected App</strong> button.</li><li>Fill out all required fields.</li><li>In the <strong>API (Enable OAuth Settings)</strong> section, tick the <strong>Enable OAuth Settings</strong> checkbox. <ul><li>In the <strong>Callback URL</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>In the <strong>Selected OAuth Scopes</strong> field, select the following permissions from the list and click <strong>Add</strong> arrow button: <ul><li><strong>Manage Pardot services (pardot_api)</strong>.</li><li><strong>Perform requests on your behalf at any time (refresh_token, offline_access)</strong>.</li></ul></li><li>Untick <strong>Require Proof Key for Code Exchange (PKCE) Extension for Supported Authorization Flows</strong>.</li><li>Tick <strong>Require Secret for Web Server Flow</strong>.</li><li>Untick <strong>Require Secret for Refresh Token Flow</strong>.</li></ul></li><li>Click the <strong>Save</strong> button.</li><li>Copy the <strong>Consumer Key</strong> from Pardot and paste in the <strong>Consumer Key</strong> field in Formie.</li><li>Copy the <strong>Consumer Secret</strong> from Pardot and paste in the <strong>Consumer Secret</strong> field in Formie.</li><li>Click on the <strong>Manage</strong> button.</li><li>Click on the <strong>Edit Policies</strong> button.</li><li>In the <strong>OAuth policies</strong> section: <ul><li>In the <strong>Permitted Users</strong> field, select <strong>All users may self-authorize</strong>.</li><li>In the <strong>IP Relaxation</strong> field, select <strong>Relaxed IP restrictions</strong>.</li></ul></li><li>Click the <strong>Save</strong> button.</li><li>In the main menu, on the top-right, click the <strong>Settings</strong> icon and select <strong>Setup</strong>.</li><li>Enter <strong>Business Unit</strong> in the Quick Find box, and click on <strong>Business Unit Setup</strong>.</li><li>Copy the <strong>Business Unit ID</strong> from Pardot and paste in the <strong>Business Unit ID</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Pardot, where you must approve Formie to access your Pardot account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the record types this integration exposes, then map the required destination fields using the variable picker. For a contact enquiry, map the visitor’s email and name where those fields are available. Use the requirements shown for your selected record type rather than assuming every CRM accepts the same fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="prospects-are-not-created-or-logs-show-api-v4-errors" tabindex="-1">Prospects Are Not Created, or Logs Show API v4 Errors <a class="header-anchor" href="#prospects-are-not-created-or-logs-show-api-v4-errors" aria-label="Permalink to &quot;Prospects Are Not Created, or Logs Show API v4 Errors&quot;">​</a></h3><p>Formie uses the Pardot <strong>API v4</strong> endpoints. If your account still uses the legacy <strong>Pardot Classic</strong> app (<code>pi.pardot.com</code>), Pardot returns an error such as <code>Your account is unable to use version 4 of the API</code> (error code <code>89</code>).</p><p>Formie does not support the legacy Pardot Classic API. You will need an <strong>Account Engagement</strong> (Salesforce Pardot) business unit and OAuth connected app, as described above.</p><p>Check <code>storage/logs/formie.log</code> after a test submission for integration errors.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Find the test record in the selected CRM destination. Check the mapped values and whether the integration created a record or updated an existing one as intended.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',18)])])}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
